{"cards": [{"node_code": "N_9d4e912c8cd11c0c", "definition": "研究以水、蒸汽或化学粘结剂为粘结介质，利用砂粒堆积形成型腔的重力铸造工艺，涵盖湿砂、干砂及自硬砂的具体应用与质量控制。", "boundary": "聚焦于非热固化或需干燥/硬化处理的砂型工艺。边界在于模具材料为松散砂粒，区别于金属模具或热固化壳型。包含湿砂型的快速生产、干砂型的强度控制及自硬砂的固化机理，适用于单件、小批量或大型铸件。", "includes": ["湿砂型铸造工艺、缺陷分析及生产流程", "干砂型铸造的烘干工艺、强度控制及适用场景", "自硬砂（如冷芯盒、热芯盒）的粘结剂体系与固化技术"], "excludes": ["使用金属模具的重力铸造工艺", "通过热固化形成薄壁壳层的壳型铸造工艺"], "sibling_distinctions": [{"other_code": "N_dae6baac2ed6d135", "rule": "本节点使用砂粒作为模具材料，兄弟节点使用金属作为模具材料。"}, {"other_code": "N_e7d7d872edd6d569", "rule": "本节点砂型通常较厚且需整体硬化或干燥，兄弟节点壳型为薄壁热固化结构，树脂砂为化学粘结整体砂型。"}], "cross_boundary_rule": "若研究重点在于砂型材料的粘结机理或强度演变，主挂载本节点；若涉及砂型制造后的浇注系统设计，需结合父节点“砂型与重力铸造”的通用规则。"}, {"node_code": "N_dae6baac2ed6d135", "definition": "研究利用金属模具（金属型）或重力模，依靠金属液重力充型凝固的铸造工艺，涵盖模具设计、热管理、表面涂层及批量生产技术。", "boundary": "聚焦于金属模具在重力铸造中的应用。边界在于模具为可重复使用的金属实体，区别于一次性砂型或薄壁壳型。包含金属型铸造的模具结构、冷却控制、排气设计，以及重力模铸造在特定合金中的应用。", "includes": ["金属型铸造的模具设计、材料选择及表面涂层技术", "重力模铸造的工艺参数、充型控制及缺陷预防", "金属型铸造的批量生产流程、模具维护及寿命管理"], "excludes": ["使用砂粒或树脂砂作为模具材料的铸造工艺", "施加高压或离心力的非重力充型工艺"], "sibling_distinctions": [{"other_code": "N_9d4e912c8cd11c0c", "rule": "本节点使用金属模具，兄弟节点使用砂粒模具。"}, {"other_code": "N_e7d7d872edd6d569", "rule": "本节点模具为整体金属块，兄弟节点壳型为薄壁热固化结构，树脂砂为化学粘结整体砂型。"}], "cross_boundary_rule": "若研究重点在于金属模具的热疲劳或涂层技术，主挂载本节点；若涉及金属型铸造后的精加工，加工部分归入“切削与精密超精密加工”。"}, {"node_code": "N_e7d7d872edd6d569", "definition": "研究利用热固化形成薄壁壳层（壳型）或化学粘结整体砂型（树脂砂）的重力铸造工艺，涵盖壳型制备、树脂砂配方及精密铸件生产。", "boundary": "聚焦于热固化壳型与化学粘结树脂砂工艺。边界在于壳型为薄壁结构且需热固化，树脂砂为化学粘结整体砂型，区别于湿砂/干砂或金属模具。包含壳型铸造的制壳工艺、树脂砂的粘结剂体系及精密铸件的质量控制。", "includes": ["壳型铸造的制壳工艺、壳层强度控制及适用合金", "树脂砂铸造的粘结剂体系、固化机理及工艺参数", "精密砂型铸造的尺寸精度控制、表面质量及缺陷预防"], "excludes": ["使用湿砂、干砂或自硬砂的传统砂型铸造工艺", "使用金属模具的重力铸造工艺"], "sibling_distinctions": [{"other_code": "N_9d4e912c8cd11c0c", "rule": "本节点壳型为薄壁热固化结构，树脂砂为化学粘结整体砂型；兄弟节点砂型较厚且需干燥或整体硬化。"}, {"other_code": "N_dae6baac2ed6d135", "rule": "本节点模具为热固化壳层或化学粘结砂型，兄弟节点模具为整体金属块。"}], "cross_boundary_rule": "若研究重点在于壳型或树脂砂的粘结剂化学或固化动力学，主挂载本节点；若涉及壳型铸造的浇注系统设计，需结合父节点“砂型与重力铸造”的通用规则。"}]}
